// No custom exception class needed. Status + message in one throw.

public class ResponseStatusExceptionDemo {
    public static void main(String[] args) {
        System.out.println("ResponseStatusException usage:");
        System.out.println("  throw new ResponseStatusException(NOT_FOUND, msg)");
        System.out.println("  Quick, inline, no custom class needed");
        System.out.println("  But: less structured than @ExceptionHandler");
    }
}
```

